obs = observe()
candidates = grasp_candidates("yellow")
chosen = None
for c in candidates:
    if c.get("hand_clear", False) and c.get("fingers_clear", False):
        chosen = c
        break
if chosen is None:
    for c in candidates:
        if c.get("fits_open_fingers", False):
            chosen = c
            break
if chosen is None:
    chosen = candidates[0]

res = grasp(chosen)
if res["holding_something"]:
    zone = obs["zones"]["green"]
    carry_to(zone["center"][0], zone["center"][1], height=0.25)
    open_gripper()
    retreat(0.1)
    go_home()
